(function () {
  'use strict';

  var replacements = [
    ["NJ's Unblocked Games", "NJ's Games"],
    ["NJs Unblocked Games", "NJs Games"],
    ["Unblocked Games", "Games"],
    ["unblocked games", "games"],
    ["Unblocker", "Proxies"],
    ["unblocker", "proxy"]
  ];

  function replaceCopy(value) {
    var next = String(value);
    replacements.forEach(function (pair) {
      next = next.split(pair[0]).join(pair[1]);
    });
    return next;
  }

  function cleanPublicCopy(root) {
    if (!root) return;
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    var node;
    while ((node = walker.nextNode())) {
      var parent = node.parentElement;
      if (parent && !/^(SCRIPT|STYLE|NOSCRIPT)$/i.test(parent.tagName)) {
        var cleaned = replaceCopy(node.nodeValue);
        if (cleaned !== node.nodeValue) node.nodeValue = cleaned;
      }
    }

    root.querySelectorAll('[title], [aria-label], [placeholder], [alt]').forEach(function (element) {
      ['title', 'aria-label', 'placeholder', 'alt'].forEach(function (attribute) {
        if (element.hasAttribute(attribute)) {
          var value = element.getAttribute(attribute);
          var cleaned = replaceCopy(value);
          if (cleaned !== value) element.setAttribute(attribute, cleaned);
        }
      });
    });
  }

  function showResponsibleUseNotice() {
    if (document.getElementById('nj-responsible-use-notice')) return;

    var overlay = document.createElement('div');
    overlay.id = 'nj-responsible-use-notice';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-labelledby', 'nj-responsible-use-title');
    overlay.style.cssText = [
      'position:fixed', 'inset:0', 'z-index:12000', 'display:flex',
      'align-items:center', 'justify-content:center', 'padding:20px',
      'background:rgba(3,3,10,.78)', 'backdrop-filter:blur(5px)',
      'font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif'
    ].join(';');

    var card = document.createElement('section');
    card.style.cssText = [
      'position:relative', 'width:min(520px,100%)', 'box-sizing:border-box',
      'padding:28px 28px 24px', 'border:1px solid #7c3aed',
      'border-radius:18px', 'background:#10101d', 'color:#e5e7eb',
      'box-shadow:0 24px 80px rgba(0,0,0,.55)'
    ].join(';');

    var title = document.createElement('h2');
    title.id = 'nj-responsible-use-title';
    title.textContent = "Welcome to NJ's Games";
    title.style.cssText = 'margin:0 0 12px;color:#fff;font-size:22px;line-height:1.25;';

    var message = document.createElement('p');
    message.textContent = "This is a collection of good games gathered in one place, so you do not need to search through other sites. Please do not use this site to bypass school, workplace, or network restrictions. Use it at home only and follow your school's rules.";
    message.style.cssText = 'margin:0;color:#c4c4d0;font-size:15px;line-height:1.65;';

    var actions = document.createElement('div');
    actions.style.cssText = 'display:flex;justify-content:flex-end;margin-top:22px;';

    var ok = document.createElement('button');
    ok.type = 'button';
    ok.textContent = 'OK, got it';
    ok.style.cssText = [
      'border:0', 'border-radius:9px', 'padding:10px 18px',
      'background:#7c3aed', 'color:#fff', 'font-size:14px',
      'font-weight:700', 'cursor:pointer'
    ].join(';');

    function dismiss() {
      overlay.remove();
    }

    ok.addEventListener('click', dismiss);

    actions.appendChild(ok);
    card.appendChild(title);
    card.appendChild(message);
    card.appendChild(actions);
    overlay.appendChild(card);
    document.body.appendChild(overlay);
    ok.focus();
  }

  function init() {
    cleanPublicCopy(document.body);
    showResponsibleUseNotice();
    var observer = new MutationObserver(function (mutations) {
      mutations.forEach(function (mutation) {
        mutation.addedNodes.forEach(function (node) {
          if (node.nodeType === Node.ELEMENT_NODE) cleanPublicCopy(node);
          if (node.nodeType === Node.TEXT_NODE && node.parentElement) {
            var cleaned = replaceCopy(node.nodeValue);
            if (cleaned !== node.nodeValue) node.nodeValue = cleaned;
          }
        });
      });
    });
    observer.observe(document.body, { childList: true, subtree: true });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init, { once: true });
  } else {
    init();
  }
}());
